// Dedupe by ticker.
export const SEED_TICKERS_DEDUP: SeedTicker[] = (() => {
  const seen = new Set<string>();
  const out: SeedTicker[] = [];
  for (const t of SEED_TICKERS) {
    if (seen.has(t.ticker)) continue;
    seen.add(t.ticker);
    out.push(t);
  }
  return out;
})();